import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    n, m = read_ints()
    graph = defaultdict(list)
    degree = [0] * (n + 1)

    for _ in range(m):
        u, v = read_ints()
        graph[u].append(v)
        graph[v].append(u)
        degree[u] += 1
        degree[v] += 1

    # Find vertices with odd degree
    odd_degree_vertices = [v for v in range(1, n + 1) if degree[v] % 2 == 1]

    if len(odd_degree_vertices) != 0 and len(odd_degree_vertices) != 2:
        print("No solution")
        return

    # BFS to find paths
    visited = [False] * (n + 1)
    path = []

    def bfs(start):
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    path.append((u, v))
                    queue.append(v)

    if odd_degree_vertices:
        bfs(odd_degree_vertices[0])
    else:
        bfs(1)

    # Output the paths
    if len(path) != m:
        print("No solution")
        return

    for (u, v) in path:
        for w in graph[v]:
            if (u, w) not in path and (w, v) not in path:
                print(u, v, w)
                break

if __name__ == "__main__":
    main()
